```java
package com.ainotepad.controller;

import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

@RestController
@RequestMapping("/api/v1")
public class NoteController {

    // In-memory draft store (prodban PostgreSQL + Redis cache kell)
    private final Map<String, String> notes = new ConcurrentHashMap<>();

    @GetMapping("/notes/{id}")
    public ResponseEntity<Map<String, Object>> getNote(@PathVariable String id) {
        String content = notes.getOrDefault(id, "");
        return ResponseEntity.ok(Map.of(
            "id", id,
            "content", content,
            "modifiedAt", System.currentTimeMillis()
        ));
    }

    @PostMapping("/notes")
    public ResponseEntity<Map<String, Object>> createNote(@RequestBody Map<String, String> payload) {
        String id = java.util.UUID.randomUUID().toString();
        notes.put(id, payload.getOrDefault("content", ""));
        return ResponseEntity.ok(Map.of("id", id, "status", "created"));
    }

    @PutMapping("/notes/{id}")
    public ResponseEntity<Map<String, Object>> updateNote(@PathVariable String id, @RequestBody Map<String, String> payload) {
        notes.merge(id, payload.getOrDefault("content", ""), (old, newVal) -> newVal);
        return ResponseEntity.ok(Map.of("status", "updated"));
    }
}
```

