package com.ainotepad.controller;

import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;
import java.util.Map;
import java.util.Random;

@RestController
@RequestMapping("/api/v1/ai")
public class AiServiceController {

    // PO p95 SLA követelmény: response time ≤ 320ms (mock latency)
    @PostMapping("/suggest")
    public ResponseEntity<Map<String, Object>> suggest(@RequestBody Map<String, String> request) {
        long start = System.currentTimeMillis();

        boolean privacyMode = Boolean.parseBoolean(request.getOrDefault("privacy_mode", "false"));
        if (privacyMode) {
            // BA Exception #1: GDPR toggle enforcement – külső API tiltása
            return ResponseEntity.ok(Map.of(
                "suggestion", "[Helyi feldolgozás kikapcsolva. Privát mód aktív.]",
                "latency_ms", System.currentTimeMillis() - start,
                "privacy_enforced", true
            ));
        }

        // Mock AI inference (valós környezetben OpenAI/Claude SDK)
        String context = request.getOrDefault("context", "");
        String suggestion = context.isEmpty() 
            ? "Nincs kontextus az elemzéshez." 
            : "Stílusjavaslat: „%s” → professzionálisabb, tömörebb szerkezet javasolt.".formatted(context.substring(0, Math.min(30, context.length())));

        long duration = System.currentTimeMillis() - start;
        return ResponseEntity.ok(Map.of(
            "suggestion", suggestion,
            "latency_ms", duration,
            "confidence", new Random().nextInt(15) + 78 // 78-92% range
        ));
    }
}
