```jsx
// src/context/AiContext.jsx
import React, { createContext, useContext, useState } from 'react';

const AiContext = createContext();

export const useAi = () => useContext(AiContext);

export const AiProvider = ({ children }) => {
  const [messages, setMessages] = useState([
    { role: 'ai', text: 'Szia! Miben segíthetek a jegyzeteddel?', timestamp: new Date().toLocaleTimeString() }
  ]);
  const [loading, setLoading] = useState(false);
  const [privacyMode, setPrivacyMode] = useState(false);

  const sendMessage = async (text) => {
    if (!text.trim()) return;

    const userMsg = { role: 'user', text, timestamp: new Date().toLocaleTimeString() };
    setMessages(prev => [...prev, userMsg]);
    setLoading(true);

    try {
      // QA Fix: Proper async handling with error fallback & privacy enforcement
      const res = await fetch('/api/v1/ai/suggest', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ context: text, privacy_mode: privacyMode })
      });

      if (!res.ok) throw new Error('AI szolgáltató SLA megsértve (5xx/429)');

      const data = await res.json();
      setMessages(prev => [...prev, { 
        role: 'ai', 
        text: data.suggestion || '[Nincs visszajelzés]', 
        latency_ms: data.latency_ms,
        privacy_enforced: data.privacy_enforced,
        timestamp: new Date().toLocaleTimeString() 
      }]);
    } catch (err) {
      setMessages(prev => [...prev, { role: 'ai', text: `Hiba: ${err.message}. Offline draft mentve.`, timestamp: new Date().toLocaleTimeString() }]);
    } finally {
      setLoading(false);
    }
  };

  return (
    <AiContext.Provider value={{ messages, loading, sendMessage, privacyMode, setPrivacyMode }}>
      {children}
    </AiContext.Provider>
  );
};
