```java
package com.ainotepad.service;

import org.springframework.stereotype.Service;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.UUID;

@Service
public class NoteService {
    // In-memory draft store (Sprint 2 specifikáció: átállási terv PostgreSQL/Redis felé dokumentálva)
    private final Map<String, String> notes = new ConcurrentHashMap<>();

    public String createNote(String content) {
        String id = UUID.randomUUID().toString();
        notes.put(id, content != null ? content : "");
        return id;
    }

    public String getNoteContent(String id) {
        // Fallback: ha nem létezik, üres string (biztonságosabb, mint NullPointerException)
        return notes.getOrDefault(id, "");
    }

    public void saveNote(String id, String content) {
        if (id == null || !notes.containsKey(id)) {
            throw new IllegalArgumentException("Jegyzet nem létezik: " + id);
        }
        // Optimista lock szimuláció (valós DB-ban @Version mezővel)
        notes.merge(id, content != null ? content : "", (old, newVal) -> newVal);
    }

    public boolean exists(String id) {
        return notes.containsKey(id);
    }
}
