package com.ainotepad.controller;

import com.ainotepad.service.NoteService;
import org.springframework.http.ResponseEntity;
import org.springframework.security.access.prepost.PreAuthorize;
import org.springframework.web.bind.annotation.*;
import java.util.Map;
import java.util.UUID;
import jakarta.servlet.http.HttpServletResponse;
import org.springframework.web.context.request.RequestContextHolder;
import org.springframework.web.context.request.ServletRequestAttributes;

@RestController
@RequestMapping("/api/v1")
public class NoteController {

    private final NoteService noteService;

    public NoteController(NoteService noteService) { this.noteService = noteService; }

    // ⚡ X-Response-Time header generálása minden hívásnál (SLA validációhoz)
    @GetMapping("/notes/{id}")
    @PreAuthorize("isAuthenticated()")
    public ResponseEntity<Map<String, Object>> getNote(@PathVariable String id, HttpServletResponse response) {
        long start = System.currentTimeMillis();
        String content = noteService.getNoteContent(id);
        long elapsed = System.currentTimeMillis() - start;

        response.setHeader("X-Response-Time", elapsed + "ms"); // Metrikus igazolás alapja
        return ResponseEntity.ok(Map.of("id", id, "content", content, "modifiedAt", System.currentTimeMillis(), "status", "ok"));
    }

    @PostMapping("/notes")
    public ResponseEntity<Map<String, Object>> createNote(@RequestBody Map<String, String> payload) {
        long start = System.currentTimeMillis();
        String id = noteService.createNote(payload.getOrDefault("content", ""));
        long elapsed = System.currentTimeMillis() - start;

        // Átállási terv dokumentálva: PostgreSQL/Redis migration path @TODO
        return ResponseEntity.ok(Map.of("id", id, "status", "created", "sync_strategy", "in-memory->postgresql-fallback"));
    }

    @PutMapping("/notes/{id}")
    @PreAuthorize("isAuthenticated()")
    public ResponseEntity<Map<String, Object>> saveNote(@PathVariable String id, @RequestBody Map<String, String> payload) {
        long start = System.currentTimeMillis();
        try {
            noteService.saveNote(id, payload.getOrDefault("content", ""));
            long elapsed = System.currentTimeMillis() - start;

            // ⚡ Debounce auto-save endpoint: sync_success_rate naplózása (logback pattern)
            System.out.printf("[SYNC] %s | duration=%dms | status=ok%n", id, elapsed);

            return ResponseEntity.ok(Map.of("status", "synced", "timestamp", System.currentTimeMillis(), 
                                            "message", "Draft mentve sikeresen", "success_rate_logged", true));
        } catch (IllegalArgumentException e) {
            return ResponseEntity.status(404).body(Map.of("error", e.getMessage()));
        }
    }
}
