    But wait, the outer ring only has positions at corners and midpoints of each side. So the outer "top" has only 3 positions: TL corner, TM midpoint, TR corner. That IS a mill line!

    Similarly for other sides... but the middle and inner rings also have this structure.

    The cross connections (vertical lines through center) are:
    - Top to bottom through center: O-TM(1), M-TM(9), I-TM(17) — then continuing down? No, there's no position below 17 on the inner ring except I-BM(21).

    Actually, the vertical center line goes:
    O-TM(1) → M-TM(9) → I-TM(17) → (gap) → I-BM(21)... no that's not right either.

    Let me just enumerate all mill lines based on the coordinate layout:
    */
];

// OK, I'll define mills by finding all sets of 3 positions where each consecutive pair is adjacent AND they form a straight line (same x or same y):

function computeMills() {
    const mills = [];

    // For each position, check if it's part of any mill with its neighbors
    for (let i = 0; i < 24; i++) {
        const px = BOARD_POSITIONS[i].x;
        const py = BOARD_POSITIONS[i].y;

        // Check horizontal mills (same y, consecutive x)
        const sameY = BOARD_POSITIONS.filter(p => p.y === py).sort((a,b) => a.x - b.x);
        if (sameY.length >= 3) {
            for (let j = 0; j <= sameY.length - 3; j++) {
                // Check if these three are actually connected in the graph
                const p1 = sameY[j].pos;
                const p2 = sameY[j+1].pos;
                const p3 = sameY[j+2].pos;

                // They must be adjacent pairs
                if (ADJ_LIST[p1].includes(p2) && ADJ_LIST[p2].includes(p3)) {
                    mills.push([p1, p2, p3]);
                }
            }
        }

        // Check vertical mills (same x, consecutive y)
        const sameX = BOARD_POSITIONS.filter(p => p.x === px).sort((a,b) => a.y - b.y);
        if (sameX.length >= 3) {
            for (let j = 0; j <= sameX.length - 3; j++) {
                const p1 = sameX[j].pos;
                const p2 = sameX[j+1].pos;
                const p3 = sameX[j+2].pos;

                if (ADJ_LIST[p1].includes(p2) && ADJ_LIST[p2].includes(p3)) {
                    mills.push([p1, p2, p3]);
                }
            }
        }
    }

    return mills;
}

const MILLS = computeMills();

// ===== UI FUNCTIONS =====

function renderBoard() {
    const cells = document.querySelectorAll('.board-cell');
    cells.forEach(cell => {
        const pos = parseInt(cell.dataset.pos);
        const piece = state.board[pos];

        // Remove all classes and reapply
        cell.className = 'board-cell';
        cell.innerHTML = '';

        if (piece) {
            cell.classList.add('has-piece');
            cell.classList.add(piece === 'black' ? 'piece-black' : 'piece-white');

            if (state.selectedPiece === pos) {
                cell.classList.add('selected');
            }
        } else {
            // Check if this is a valid move target
            if (isValidMoveTarget(pos)) {
                cell.classList.add('valid-move');
                cell.style.background = 'radial-gradient(circle, rgba(99,102,241,0.2), transparent)';
                cell.innerHTML = '<div class="w-full h-full rounded-full bg-indigo-500/30"></div>';
            } else {
                cell.style.background = '';
            }
        }
    });
}

function isValidMoveTarget(pos) {
    if (state.gameOver) return false;
    if (state.board[pos] !== null) return false;

    if (state.phase === 'placing') {
        // Valid during placement phase for current player
        return true;
    }

    if (state.phase === 'moving') {
        // During flying: any empty spot is valid
        const piecesOnBoard = state.board.filter(p => p === state.currentPlayer).length;
        if (piecesOnBoard <= 3) {
            return true; // Can fly to any empty position
        }

        // Normal movement: only adjacent empty positions
        const currentPieces = [];
        for (let i = 0; i < 24; i++) {
            if (state.board[i] === state.currentPlayer) {
                currentPieces.push(i);
            }
        }

        // If a piece is selected, check adjacency
        if (state.selectedPiece !== null) {
            return ADJ_LIST[state.selectedPiece].includes(pos);
        }
    }

    if (state.phase === 'removing') {
        return true; // Any opponent's piece can be removed
    }

    return false;
}

function handleCellClick(pos) {
    if (state.gameOver) return;
    if (state.gameMode === 'ai' && state.currentPlayer === 'white') return;

    const piece = state.board[pos];

    // Phase: removing opponent's piece after mill
    if (state.phase === 'removing') {
        if (piece && piece !== state.currentPlayer) {
            // Check if it's part of a mill — can only remove non-mill pieces unless all are in mills
            const millsForPiece = MILLS.filter(m => m.includes(pos));
            const allOpponentMills = millsForPiece.every(m => 
                m.every(p => state.board[p] === (state.currentPlayer === 'black' ? 'white' : 'black'))
            );

            if (!allOpponentMills) {
                showToast('Ez a malomban van — csak nem malom darabot lehet eltávolítani!', 'warning');
                return;
            }

            removePiece(pos);
        } else if (piece && piece === state.currentPlayer) {
            showToast('Saját darabot nem lehet eltávolítani!'), 'error';
            return;
        } else {
            showToast('Üres helyre nem lehet eltávolítani!', 'warning');
            return;
        }
        return;
    }

    // Phase: placing pieces
    if (state.phase === 'placing') {
        if (piece) {
            showToast('Ez a pozíció már foglalt!', 'warning');
            return;
        }

        placePiece(pos);
        return;
    }

    // Phase: moving pieces
    if (state.phase === 'moving') {
        const piecesOnBoard = state.board.filter(p => p === state.currentPlayer).length;

        if (piecesOnBoard <= 3) {
            // Flying phase — can move to any empty position
            if (!piece && pos !== state.selectedPiece) {
                movePiece(state.selectedPiece, pos);
            } else if (piece === state.currentPlayer) {
                selectPiece(pos);
            }
        } else {
            // Normal movement
            if (piece === state.currentPlayer) {
                selectPiece(pos);
            } else if (state.selectedPiece !== null && piece === null) {
                // Check adjacency
                if (ADJ_LIST[state.selectedPiece].includes(pos)) {
                    movePiece(state.selectedPiece, pos);
                } else {
                    showToast('Nem szomszédos pozícióra nem lehet lépni!', 'warning');
                }
            }
        }
    }
}

function selectPiece(pos) {
    state.selectedPiece = pos;
    renderBoard();
    highlightValidMoves();
}

function placePiece(pos) {
    // Save state for undo
    state.moveHistory.push({
        type: 'place',
        player: state.currentPlayer,
        position: pos,
        board: [...state.board],
        piecesToPlaceBlack: state.piecesToPlaceBlack,
        piecesToPlaceWhite: state.piecesToPlaceWhite,
        phase: state.phase,
    });

    state.board[pos] = state.currentPlayer;

    if (state.currentPlayer === 'black') {
        state.piecesToPlaceBlack--;
    } else {
        state.piecesToPlaceWhite--;
    }

    addMoveLog(state.currentPlayer === 'black' ? 'Fekete' : 'Fehér', `Elhelyezés → pozíció ${pos}`);

    // Check for mill
    if (checkMill(pos)) {
        state.phase = 'removing';
        showToast('Malom! Távolíts el egy ellenfél darabot!', 'mill');
        updateUI();

        // AI turn for removal
        if (state.gameMode === 'ai' && state.currentPlayer === 'white') {
            setTimeout(() => aiRemovePiece(), 600);
        }
        return;
    }

    switchTurn();
}

function selectPiece(pos) {
    state.selectedPiece = pos;
    renderBoard();
    highlightValidMoves();
}

function movePiece(from, to) {
    // Save state for undo
    state.moveHistory.push({
        type: 'move',
        player: state.currentPlayer,
        from: from,
        to: to,
        board: [...state.board],
        phase: state.phase,
        selectedPiece: state.selectedPiece,
    });

    state.board[to] = state.board[from];
    state.board[from] = null;
    state.selectedPiece = null;

    addMoveLog(state.currentPlayer === 'black' ? 'Fekete' : 'Fehér', `Lépés: ${from} → ${to}`);

    // Check for mill
    if (checkMill(to)) {
        state.phase = 'removing';
        showToast('Malom! Távolíts el egy ellenfél darabot!', 'mill');
        updateUI();

        if (state.gameMode === 'ai' && state.currentPlayer === 'white') {
            setTimeout(() => aiRemovePiece(), 600);
        }
        return;
    }

    switchTurn();
}

function removePiece(pos) {
    // Save state for undo
    state.moveHistory.push({
        type: 'remove',
        player: state.currentPlayer,
        position: pos,
        board: [...state.board],
        phase: state.phase,
    });

    const opponent = state.currentPlayer === 'black' ? 'white' : 'black';
    state.board[pos] = null;
    state.removedCount++;
    state.millCount++;

    addMoveLog(state.currentPlayer === 'black' ? 'Fekete' : 'Fehér', `Eltávolítás → pozíció ${pos}`);

    state.phase = state.piecesToPlaceBlack > 0 || state.piecesToPlaceWhite > 0 
        ? (state.currentPlayer === 'black' && state.piecesToPlaceBlack > 0 ? 'placing' : 'placing')
        : 'moving';

    // Ensure correct phase after removal
    if (state.piecesToPlaceBlack <= 0 && state.piecesToPlaceWhite <= 0) {
        state.phase = 'moving';
    }

    state.selectedPiece = null;

    // Check win condition: opponent has fewer than 3 pieces and can't move
    checkWinCondition();

    switchTurn();
}

function checkMill(pos) {
    const piece = state.board[pos];
    for (const mill of MILLS) {
        if (mill.includes(pos) && 
            mill.every(p => state.board[p] === piece)) {
            return true;
        }
    }
    return false;
}

function switchTurn() {
    const prevPlayer = state.currentPlayer;
    state.currentPlayer = state.currentPlayer === 'black' ? 'white' : 'black';

    // Ensure phase is correct
    if (state.piecesToPlaceBlack > 0 && state.currentPlayer === 'black') {
        state.phase = 'placing';
    } else if (state.piecesToPlaceWhite > 0 && state.currentPlayer === 'white') {
        state.phase = 'placing';
    } else {
        state.phase = 'moving';
    }

    // Check if current player can move
    if (!canPlayerMove(state.currentPlayer)) {
        endGame(prevPlayer, `${state.currentPlayer === 'black' ? 'Fekete' : 'Fehér'} nem tud lépni!`);
        return;
    }

    updateUI();

    // AI turn
    if (state.gameMode === 'ai' && state.currentPlayer === 'white' && !state.gameOver) {
        setTimeout(() => aiMove(), 800 + Math.random() * 400);
    }
}

function canPlayerMove(player) {
    // During placing: always can place if pieces remain
    if (player === 'black' && state.piecesToPlaceBlack > 0) return true;
    if (player === 'white' && state.piecesToPlaceWhite > 0) return true;

    // During moving/flying: check if any move is possible
    const piecesOnBoard = [];
    for (let i = 0; i < 24; i++) {
        if (state.board[i] === player) piecesOnBoard.push(i);
    }

    if (piecesOnBoard.length <= 3) return true; // Can fly

    // Check adjacency to empty spots
    for (const pos of piecesOnBoard) {
        for (const adjPos of ADJ_LIST[pos]) {
            if (state.board[adjPos] === null) return true;
        }
    }

    return false;
}

function checkWinCondition() {
    const blackPieces = state.board.filter(p => p === 'black').length;
    const whitePieces = state.board.filter(p => p === 'white').length;

    if (state.piecesToPlaceBlack <= 0 && state.piecesToPlaceWhite <= 0) {
        // Placement phase over — check for win by piece count
        if (blackPieces < 3) {
            endGame('white', 'A Fekete kevesebb mint 3 darabot tud tartani a táblán!');
            return;
        }
        if (whitePieces < 3) {
            endGame('black', 'A Fehér kevesebb mint 3 darabot tud tartani a táblán!');
            return;
        }
    }
}

function endGame(winner, reason) {
    state.gameOver = true;

    const winnerName = winner === 'black' ? 'Fekete (Játékos 1)' : 'Fehér (Játékos 2)';
    document.getElementById('gameover-title').textContent = `${winnerName} győzött!`;
    document.getElementById('gameover-subtitle').textContent = reason;

    const modal = document.getElementById('gameover-modal');
    modal.classList.remove('hidden');
    modal.classList.add('flex');

    showToast(`🏆 ${winnerName} győzött!`, 'success');
}

function closeGameOver() {
    const modal = document.getElementById('gameover-modal');
    modal.classList.add('hidden');
    modal.classList.remove('flex');
}

// ===== AI =====

function aiMove() {
    if (state.gameOver || state.currentPlayer !== 'white') return;

    // Simulate thinking time based on difficulty
    const thinkTime = [300, 600, 1200][state.difficulty];

    setTimeout(() => {
        if (state.phase === 'placing') {
            aiPlacePiece();
        } else if (state.phase === 'moving' || state.phase === 'removing') {
            aiMoveOrRemove();
        }
    }, thinkTime);
}

function aiPlacePiece() {
    const emptyPositions = [];
    for (let i = 0; i < 24; i++) {
        if (!state.board[i]) emptyPositions.push(i);
    }

    // AI strategy: prefer positions that complete a mill, then block opponent mills, then center
    let bestPos = emptyPositions[Math.floor(Math.random() * emptyPositions.length)];
    let bestScore = -1;

    for (const pos of emptyPositions) {
        let score = 0;

        // Check if placing here completes a mill
        state.board[pos] = 'white';
        if (checkMill(pos)) score += 100;
        state.board[pos] = null;

        // Check if it blocks an opponent mill
        state.board[pos] = 'black';
        let blocksMill = false;
        for (const mill of MILLS) {
            if (mill.includes(pos)) {
                const otherTwo = mill.filter(p => p !== pos);
                if (otherTwo.every(p => state.board[p] === 'black')) {
                    blocksMill = true;
                    break;
                }
            }
        }
        if (blocksMill) score += 50;
        state.board[pos] = null;

        // Prefer center positions
        const px = BOARD_POSITIONS[pos].x;
        const py = BOARD_POSITIONS[pos].y;
        const distFromCenter = Math.abs(px - 4) + Math.abs(py - 4);
        score += (8 - distFromCenter) * 2;

        // Prefer positions with more connections
        score += ADJ_LIST[pos].length;

        if (score > bestScore) {
            bestScore = score;
            bestPos = pos;
        }
    }

    placePiece(bestPos);
}

function aiMoveOrRemove() {
    if (state.phase === 'removing') {
        aiRemovePiece();
        return;
    }

    // AI moving phase
    const piecesOnBoard = [];
    for (let i = 0; i < 24; i++) {
        if (state.board[i] === 'white') piecesOnBoard.push(i);
    }

    const canFly = piecesOnBoard.length <= 3;

    let bestMove = null;
    let bestScore = -Infinity;

    for (const from of piecesOnBoard) {
        const targets = canFly 
            ? Array.from({length: 24}, (_, i) => i).filter(i => !state.board[i])
            : ADJ_LIST[from].filter(to => !state.board[to]);

        for (const to of targets) {
            let score = 0;

            // Simulate move
            state.board[to] = 'white';
            state.board[from] = null;

            if (checkMill(to)) score += 100;
            if (!canFly && ADJ_LIST[to].filter(t => !state.board[t]).length > 2) score += 5; // Mobility

            state.board[from] = 'white';
            state.board[to] = null;

            // Avoid positions that create opponent mills
            const oppMillsHere = MILLS.filter(m => {
                if (!m.includes(to)) return false;
                m.forEach(p => { if (p !== to) state.board[p] = 'black'; });
                const isMill = m.every(p => state.board[p] === 'black');
                m.forEach(p => { if (p !== to) delete state.board[p]; });
                return isMill;
            }).length;
            score -= oppMillsHere * 30;

            // Prefer center
            const px = BOARD_POSITIONS[to].x;
            const py = BOARD_POSITIONS[to].y;
            score += (8 - Math.abs(px-4) - Math.abs(py-4)) * 2;

            if (score > bestScore) {
                bestScore = score;
                bestMove = { from, to };
            }
        }
    }

    if (bestMove && bestScore > -Infinity) {
        movePiece(bestMove.from, bestMove.to);
    } else {
        // No valid moves — should have been caught by canPlayerMove
        const prevPlayer = 'black';
        endGame(prevPlayer, 'A Fehér nem tud lépni!');
    }
}

function aiRemovePiece() {
    if (state.phase !== 'removing') return;

    const opponentPieces = [];
    for (let i = 0; i < 24; i++) {
        if (state.board[i] === 'black') opponentPieces.push(i);
    }

    // Prefer removing pieces not in mills, then any piece
    let removable = opponentPieces.filter(p => !isInMill(p, 'black'));
    if (removable.length === 0) {
        removable = opponentPieces; // All are in mills — can remove any
    }

    const pos = removable[Math.floor(Math.random() * removable.length)];
    removePiece(pos);
}

function isInMill(pos, player) {
    return MILLS.some(m => m.includes(pos) && m.every(p => state.board[p] === player));
}

// ===== UI UPDATE FUNCTIONS =====

function updateUI() {
    renderBoard();

    // Update player info cards
    const blackOnBoard = state.board.filter(p => p === 'black').length;
    const whiteOnBoard = state.board.filter(p => p === 'white').length;

    document.getElementById('p1-pieces-left').textContent = state.piecesToPlaceBlack;
    document.getElementById('p1-on-board').textContent = blackOnBoard;
    document.getElementById('p2-pieces-left').textContent = state.piecesToPlaceWhite;
    document.getElementById('p2-on-board').textContent = whiteOnBoard;

    // Phase indicators
    const phaseNames = { placing: 'Elhelyezés', moving: 'Mozgatás', removing: 'Eltávolítás' };
    document.getElementById('player1-phase').textContent = state.currentPlayer === 'black' ? phaseNames[state.phase] : 'Várakozik';
    document.getElementById('player2-phase').textContent = state.currentPlayer === 'white' ? phaseNames[state.phase] : 'Várakozik';

    // Mobile phases
    document.getElementById('mob-p1-phase').textContent = state.currentPlayer === 'black' ? phaseNames[state.phase] : 'Várakozik';
    document.getElementById('mob-p2-phase').textContent = state.currentPlayer === 'white' ? phaseNames[state.phase] : 'Várakozik';

    // Turn indicator
    const turnDot = document.getElementById('turn-dot');
    const turnText = document.getElementById('turn-text');
    if (state.currentPlayer === 'black') {
        turnDot.className = 'w-3 h-3 rounded-full bg-indigo-400 animate-pulse';
        turnText.textContent = 'Játékos 1 (Fekete) köre';
        document.getElementById('player1-card').classList.add('border-indigo-500/30', 'shadow-lg', 'shadow-indigo-500/10');
        document.getElementById('player1-card').style.opacity = '1';
        document.getElementById('player2-card').style.opacity = '0.6';
    } else {
        turnDot.className = 'w-3 h-3 rounded-full bg-gray-400 animate-pulse';
        turnText.textContent = state.gameMode === 'ai' ? 'AI (Fehér) gondolkozik...' : 'Játékos 2 (Fehér) köre';
        document.getElementById('player2-card').style.opacity = '1';
        document.getElementById('player1-card').style.opacity = '0.6';
    }

    // Phase label
    const phaseLabel = document.getElementById('phase-label');
    if (state.phase === 'placing') {
        phaseLabel.textContent = state.piecesToPlaceBlack > 0 || state.piecesToPlaceWhite > 0 ? 'Elhelyezési fázis' : 'Mozgási fázis';
    } else if (state.phase === 'moving') {
        const piecesLeft = state.currentPlayer === 'black' ? state.piecesToPlaceBlack : state.piecesToPlaceWhite;
        if (piecesLeft > 0) phaseLabel.textContent = 'Elhelyezési fázis';
        else phaseLabel.textContent = 'Mozgási fázis';
    } else {
        phaseLabel.textContent = 'Malom! Eltávolítás';
    }

    // Stats
    document.getElementById('move-count').textContent = state.moveHistory.length;
    document.getElementById('removed-count').textContent = state.removedCount;
    document.getElementById('mill-count').textContent = state.millCount;

    // Reserve dots
    renderReserveDots();
}

function renderReserveDots() {
    const p1Container = document.getElementById('p1-reserve-dots');
    const p2Container = document.getElementById('p2-reserve-dots');

    let p1Html = '';
    for (let i = 0; i < state.piecesToPlaceBlack; i++) {
        p1Html += '<div class="w-3 h-3 rounded-full bg-gray-500 border border-white/20"></div>';
    }
    p1Container.innerHTML = p1Html || '<span class="text-[9px] text-green-400">✓ Minden darab letéve</span>';

    let p2Html = '';
    for (let i = 0; i < state.piecesToPlaceWhite; i++) {
        p2Html += '<div class="w-3 h-3 rounded-full bg-gray-400 border border-white/10"></div>';
    }
    p2Container.innerHTML = p2Html || '<span class="text-[9px] text-green-400">✓ Minden darab letéve</span>';
}

function highlightValidMoves() {
    // Highlight valid move targets for selected piece
    const cells = document.querySelectorAll('.board-cell');

    if (state.selectedPiece === null || state.phase !== 'moving') return;

    const piecesOnBoard = state.board.filter(p => p === state.currentPlayer).length;
    let targets = [];

    if (piecesOnBoard <= 3) {
        // Flying: all empty positions
        for (let i = 0; i < 24; i++) {
            if (!state.board[i]) targets.push(i);
        }
    } else {
        // Normal: adjacent empty positions
        targets = ADJ_LIST[state.selectedPiece].filter(pos => !state.board[pos]);
    }

    cells.forEach(cell => {
        const pos = parseInt(cell.dataset.pos);
        if (targets.includes(pos)) {
            cell.classList.add('valid-move');
            cell.style.background = 'radial-gradient(circle, rgba(99,102,241,0.2), transparent)';
            cell.innerHTML = '<div class="w-full h-full rounded-full bg-indigo-500/30"></div>';
        }
    });
}

function addMoveLog(player, action) {
    const log = document.getElementById('move-log');

    if (state.moveHistory.length === 1) {
        log.innerHTML = '';
    }

    const entry = document.createElement('p');
    entry.className = 'text-xs text-gray-400';
    entry.innerHTML = `<span class="font-medium ${player === 'Fekete' ? 'text-indigo-300' : 'text-gray-300'}">${player}</span> <span class="text-gray-600">→</span> ${action}`;

    log.prepend(entry);

    // Keep only last 15 entries
    while (log.children.length > 15) {
        log.removeChild(log.lastChild);
    }
}

function showToast(message, type = 'info') {
    const container = document.getElementById('toast-container');
    const toast = document.createElement('div');

    const colors = {
        info: 'bg-surface3 border-gray-600 text-gray-200',
        warning: 'bg-yellow-950/80 border-yellow-700 text-yellow-200',
        success: 'bg-emerald-950/80 border-emerald-700 text-emerald-200',
        mill: 'bg-accent/30 border-indigo-500 text-indigo-100',
        error: 'bg-red-950/80 border-red-700 text-red-200',
    };

    toast.className = `pointer-events-auto px-4 py-2.5 rounded-xl border ${colors[type] || colors.info} text-xs font-medium shadow-lg backdrop-blur-sm`;
    toast.textContent = message;

    container.appendChild(toast);

    setTimeout(() => {
        toast.style.animation = 'fadeOut 0.3s ease forwards';
        setTimeout(() => toast.remove(), 300);
    }, 2500);
}

// ===== GAME CONTROLS =====

function newGame() {
    state.board = new Array(24).fill(null);
    state.currentPlayer = 'black';
    state.phase = 'placing';
    state.piecesToPlaceBlack = 9;
    state.piecesToPlaceWhite = 9;
    state.selectedPiece = null;
    state.moveHistory = [];
    state.removedCount = 0;
    state.millCount = 0;
    state.gameOver = false;

    document.getElementById('move-log').innerHTML = '<p class="text-xs text-gray-500 italic">A játék kezdődik... Fekete kezd.</p>';

    updateUI();
}

function undoMove() {
    if (state.moveHistory.length === 0) return;

    const lastMove = state.moveHistory.pop();

    // Restore entire game state from snapshot
    state.board = [...lastMove.board];
    state.currentPlayer = lastMove.player;
    state.phase = lastMove.type === 'place' 
        ? (lastMove.piecesToPlaceBlack !== undefined ? (state.piecesToPlaceBlack > 0 || state.piecesToPlaceWhite > 0 ? 'placing' : 'moving') : 'placing')
        : lastMove.phase;

    if (lastMove.type === 'place') {
        state.piecesToPlaceBlack = lastMove.piecesToPlaceBlack;
        state.piecesToPlaceWhite = lastMove.piecesToPlaceWhite;
    } else if (lastMove.type === 'remove') {
        // Recalculate removed count
        const blackPieces = state.board.filter(p => p === 'black').length;
        const whitePieces = state.board.filter(p => p === 'white').length;
        state.removedCount = 18 - blackPieces - whitePieces;
    } else if (lastMove.type === 'move') {
        // Recalculate removed count
        const blackPieces = state.board.filter(p => p === 'black').length;
        const whitePieces = state.board.filter(p => p === 'white').length;
        state.removedCount = 18 - blackPieces - whitePieces;
    }

    if (lastMove.type !== 'move') {
        // For place/remove, revert removed count too
        const blackPieces = state.board.filter(p => p === 'black').length;
        const whitePieces = state.board.filter(p => p === 'white').length;
        state.removedCount = 18 - blackPieces - whitePieces;
    }

    // Recalculate mill count from history
    let mills = 0;
    for (const m of state.moveHistory) {
        if (m.type === 'place' || m.type === 'move') {
            const pos = m.position !== undefined ? m.position : m.to;
            if (pos !== undefined) {
                // Check if this move created a mill
                for (const mill of MILLS) {
                    if (mill.includes(pos) && 
                        mill.every(p => state.board[p] === m.player)) {
                        mills++;
                        break;
                    }
                }
            }
        }
    }
    // Simpler: just count from history
    let totalRemoves = 0;
    for (const m of state.moveHistory) {
        if (m.type === 'remove') totalRemoves++;
    }

    state.selectedPiece = null;
    updateUI();
    showToast('Lépés visszavonva', 'info');
}

function setDifficulty(level) {
    state.difficulty = level;

    document.querySelectorAll('.diff-btn').forEach(btn => {
        btn.classList.remove('active', 'bg-accent/20', 'text-indigo-300', 'border-accent/30');
        btn.classList.add('bg-surface3', 'text-gray-400', 'border-transparent');
    });

    const activeBtn = document.querySelector(`[data-diff="${level}"]`);
    activeBtn.classList.remove('bg-surface3', 'text-gray-400', 'border-transparent');
    activeBtn.classList.add('active', 'bg-accent/20', 'text-indigo-300', 'border-accent/30');

    const names = ['Könnyű', 'Közepes', 'Nehéz'];
    showToast(`AI nehézség: ${names[level]}`, 'info');
}

function setGameMode(mode) {
    state.gameMode = mode;

    document.getElementById('mode-pvp').className = `flex-1 py-1.5 text-xs font-medium rounded-md transition-all ${mode === 'pvp' ? 'bg-accent text-white' : 'text-gray-400 hover:text-white'}`;
    document.getElementById('mode-ai').className = `flex-1 py-1.5 text-xs font-medium rounded-md transition-all ${mode === 'ai' ? 'bg-accent text-white' : 'text-gray-400 hover:text-white'}`;

    showToast(`Játékmód: ${mode === 'pvp' ? '2 játékos (PvP)' : 'vs AI'}`, 'info');
}

function setFirstPlayer(player) {
    state.firstPlayer = player;
    document.getElementById('first-black').className = `flex-1 py-1.5 text-xs font-medium rounded-md transition-all ${player === 'black' ? 'bg-accent text-white' : 'text-gray-400 hover:text-white'}`;
    document.getElementById('first-white').className = `flex-1 py-1.5 text-xs font-medium rounded-md transition-all ${player === 'white' ? 'bg-accent text-white' : 'text-gray-400 hover:text-white'}`;
}

function toggleSettings() {
    const modal = document.getElementById('settings-modal');
    if (modal.classList.contains('hidden')) {
        modal.classList.remove('hidden');
        modal.classList.add('flex');
    } else {
        modal.classList.add('hidden');
        modal.classList.remove('flex');
    }
}

// ===== INITIALIZATION =====

document.addEventListener('DOMContentLoaded', () => {
    newGame();

    // Log mill lines for debugging
    console.log('Mill lines:', MILLS.map(m => m.join('-')).join(', '));
    console.log('Adjacency:', Object.fromEntries(Object.entries(ADJ_LIST).map(([k,v]) => [k, v])));
});

// Keyboard shortcuts
document.addEventListener('keydown', (e) => {
    if (e.key === 'z' && (e.ctrlKey || e.metaKey)) {
        e.preventDefault();
        undoMove();
    }
    if (e.key === 'n' && (e.ctrlKey || e.metaKey)) {
        e.preventDefault();
        newGame();
    }
    if (e.key === 'Escape') {
        closeGameOver();
        const settings = document.getElementById('settings-modal');
        if (!settings.classList.contains('hidden')) toggleSettings();
    }
});
</script>

